class FileStore:
    def __init__(self):
        self.files = {"data/cards.json": "old"}
    def write(self, path, text):
        self.files[path] = text
    def replace(self, src, dst):
        self.files[dst] = self.files.pop(src)

store = FileStore()
tmp = "data/cards.tmp.json"
out = "data/cards.json"
store.write(tmp, "new-json")
store.replace(tmp, out)
final_text = store.files[out]

